import {
  IHikingMenuExtendedProduct,
  IHikingMenuFood,
} from '../../../../../@types/hikingMenu.types';

export const getHikingMenuWeightSummary = (
  foods: IHikingMenuFood[],
  products: IHikingMenuExtendedProduct[],
  membersCount: number,
) => {
  const dateUserWeightAggregation: Record<string, Record<number, number>> = {};
  const userTotalAggregation: Record<
    number,
    { user: IHikingMenuExtendedProduct['forcedUser']; forcedAmount: number; amount: number }
  > = {};

  const forcedProducts: Array<number> = [];

  products.forEach((product) => {
    if (product.forcedUser) {
      if (!userTotalAggregation[product.forcedUser.id]) {
        userTotalAggregation[product.forcedUser.id] = {
          user: { ...product.forcedUser },
          forcedAmount: 0,
          amount: 0,
        };
      }
      userTotalAggregation[product.forcedUser.id].forcedAmount += product.amount;
      forcedProducts.push(product.id);
    }
  });

  foods.forEach((food) => {
    if (food.assigneeUser) {
      if (!userTotalAggregation[food.assigneeUser.id]) {
        userTotalAggregation[food.assigneeUser.id] = {
          user: { ...food.assigneeUser },
          forcedAmount: 0,
          amount: 0,
        };
      }
    }

    const k = food.date.toISOString();
    const userKey = food?.assigneeUser?.id || 0;
    if (!dateUserWeightAggregation[k]) {
      dateUserWeightAggregation[k] = {};
    }
    if (!dateUserWeightAggregation[k][userKey]) {
      dateUserWeightAggregation[k][userKey] = 0;
    }

    food.products.forEach((product) => {
      if (!forcedProducts.includes(product.id)) {
        userTotalAggregation[userKey] &&
          (userTotalAggregation[userKey].amount += product.amount * food.correction);
        dateUserWeightAggregation[k][userKey] += product.amount * food.correction;
      } else {
        const fu = products.find((p) => p.id === product.id)?.forcedUser?.id || 0;

        if (!dateUserWeightAggregation[k][fu]) {
          dateUserWeightAggregation[k][fu] = 0;
        }
        dateUserWeightAggregation[k][fu] += product.amount * food.correction;
      }
    });
  });

  const maxUserLoads: Record<number, number> = Object.keys(userTotalAggregation).reduce(
    (acc, val) => ({
      ...acc,
      [+val]:
        (userTotalAggregation[+val].amount + userTotalAggregation[+val].forcedAmount) *
        membersCount,
    }),
    {},
  );

  return { dateUserWeightAggregation, userTotalAggregation, maxUserLoads };
};
